'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var EPS = require( '@stdlib/constants/float64/eps' );
var tryRequire = require( '@stdlib/utils/try-require' );


// VARIABLES //

var dindexOfAlmostSameValue = tryRequire( resolve( __dirname, './../lib/ndarray.native.js' ) );
var opts = {
	'skip': ( dindexOfAlmostSameValue instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dindexOfAlmostSameValue, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 6', opts, function test( t ) {
	t.strictEqual( dindexOfAlmostSameValue.length, 6, 'has expected arity' );
	t.end();
});

tape( 'the function returns the first index of an element which is almost the same value as a provided search element', opts, function test( t ) {
	var actual;
	var x;

	x = new Float64Array( [ 1.0, 1.0, 2.0, 2.0, 3.0, 3.0 ] );

	actual = dindexOfAlmostSameValue( x.length, 1.0, 1, x, 1, 0 );
	t.strictEqual( actual, 0, 'returns expected value' );

	t.end();
});

tape( 'the function returns `-1` if unable to find a search element', opts, function test( t ) {
	var actual;
	var x;

	x = new Float64Array( [ 1.0, 1.0, 2.0, 2.0, 3.0, 3.0 ] );

	actual = dindexOfAlmostSameValue( x.length, 4.0, 1, x, 1, 0 );
	t.strictEqual( actual, -1, 'returns expected value' );

	t.end();
});

tape( 'the function supports specifying a maximum allowed ULP difference', opts, function test( t ) {
	var actual;
	var x;

	x = new Float64Array( [ 1.0+( 4.0*EPS ), 1.0+( 2.0*EPS ), 1.0+EPS ] );

	actual = dindexOfAlmostSameValue( x.length, 1.0, 0, x, 1, 0 );
	t.strictEqual( actual, -1, 'returns expected value' );

	actual = dindexOfAlmostSameValue( x.length, 1.0, 1, x, 1, 0 );
	t.strictEqual( actual, 2, 'returns expected value' );

	actual = dindexOfAlmostSameValue( x.length, 1.0, 2, x, 1, 0 );
	t.strictEqual( actual, 1, 'returns expected value' );

	actual = dindexOfAlmostSameValue( x.length, 1.0, 4, x, 1, 0 );
	t.strictEqual( actual, 0, 'returns expected value' );

	t.end();
});

tape( 'the function returns `-1` if a provided `N` parameter is less than or equal to zero', opts, function test( t ) {
	var actual;

	actual = dindexOfAlmostSameValue( 0, 2.0, 1, new Float64Array( [ 1.0, 2.0, 3.0 ] ), 1, 0 );
	t.strictEqual( actual, -1, 'returns expected value' );

	actual = dindexOfAlmostSameValue( -1, 2.0, 1, new Float64Array( [ 1.0, 2.0, 3.0 ] ), 1, 0 );
	t.strictEqual( actual, -1, 'returns expected value' );

	t.end();
});

tape( 'the function treats `NaN` values as the same', opts, function test( t ) {
	var actual;

	actual = dindexOfAlmostSameValue( 1, NaN, 1, new Float64Array( [ NaN ] ), 1, 0 );
	t.strictEqual( actual, 0, 'returns expected value' );

	actual = dindexOfAlmostSameValue( 1, NaN, 1, new Float64Array( [ 1.0 ] ), 1, 0 );
	t.strictEqual( actual, -1, 'returns expected value' );

	t.end();
});

tape( 'the function treats -0 and +0 as distinct', opts, function test( t ) {
	var actual;

	actual = dindexOfAlmostSameValue( 1, 0.0, 0, new Float64Array( [ -0.0 ] ), 1, 0 );
	t.strictEqual( actual, -1, 'returns expected value' );

	actual = dindexOfAlmostSameValue( 1, -0.0, 0, new Float64Array( [ 0.0 ] ), 1, 0 );
	t.strictEqual( actual, -1, 'returns expected value' );

	actual = dindexOfAlmostSameValue( 1, 0.0, 0, new Float64Array( [ 0.0 ] ), 1, 0 );
	t.strictEqual( actual, 0, 'returns expected value' );

	actual = dindexOfAlmostSameValue( 1, -0.0, 0, new Float64Array( [ -0.0 ] ), 1, 0 );
	t.strictEqual( actual, 0, 'returns expected value' );

	t.end();
});

tape( 'the function supports an `x` stride', opts, function test( t ) {
	var actual;
	var x;

	x = new Float64Array([
		1.0, // 0
		2.0,
		3.0, // 1
		4.0,
		5.0  // 2
	]);

	actual = dindexOfAlmostSameValue( 3, 3.0, 1, x, 2, 0 );
	t.strictEqual( actual, 1, 'returns expected value' );

	t.end();
});

tape( 'the function supports a negative `x` stride', opts, function test( t ) {
	var actual;
	var x;

	x = new Float64Array([
		1.0, // 2
		2.0,
		3.0, // 1
		4.0,
		5.0  // 0
	]);

	actual = dindexOfAlmostSameValue( 3, 3.0, 1, x, -2, 4 );
	t.strictEqual( actual, 1, 'returns expected value' );

	t.end();
});

tape( 'the function supports an `x` offset', opts, function test( t ) {
	var actual;
	var x;

	x = new Float64Array([
		1.0,
		2.0, // 0
		3.0, // 1
		4.0, // 2
		5.0
	]);

	actual = dindexOfAlmostSameValue( 3, 4.0, 1, x, 1, 1 );
	t.strictEqual( actual, 2, 'returns expected value' );

	t.end();
});

tape( 'the function supports complex access patterns', opts, function test( t ) {
	var actual;
	var x;

	x = new Float64Array([
		1.0,
		2.0, // 0
		3.0,
		4.0, // 1
		5.0,
		6.0  // 2
	]);

	actual = dindexOfAlmostSameValue( 3, 4.0, 1, x, 2, 1 );
	t.strictEqual( actual, 1, 'returns expected value' );

	t.end();
});
